try {
    var isSameScreen = location.href.indexOf("sameScreen=true") > -1;
    var originUrl = location.hostname === "localhost" ? "https://dmzstg1.pa18.com" : location.origin;
    var isTest = originUrl.indexOf("dmzstg1") > -1 || originUrl.indexOf("dmzstg2") > -1;
    var baseSdkUrl = isTest ? "https://interwork-cdn-stg.itp-live.pingan.com.cn" : "https://interwork-cdn.itp-live.pingan.com.cn";
    // 初始化 SDK
    var initSDK = function () {
    if (window.PAInterwork) {
    new PAInterwork({
    target: document.body,
    props: {
    enableClickToTouch: true,
    env: !isTest ? 2 : 0, // prd是2、stg1是0、stg2是1
    },
    })
    }
    }
    if (isSameScreen) {
    (function () {
    // 引入同屏SDK样式
    var styleEl = document.createElement("link");
    styleEl.rel = "stylesheet";
    styleEl.href = baseSdkUrl + "/interwork/sdk/pa-interwork.css";
    var styleTag = document.getElementsByTagName("link")[0];
    styleTag.parentNode.insertBefore(styleEl, styleTag);
    // 引入同屏jssdk
    var scriptEl = document.createElement("script");
    scriptEl.src = baseSdkUrl + "/interwork/sdk/pa-interwork-umd.js?pa_interwork_channel=cx";
    var scriptTag = document.getElementsByTagName("script")[0];
    scriptTag.parentNode.insertBefore(scriptEl, scriptTag);
    if (scriptEl.addEventListener) {
    scriptEl.addEventListener('load', function () {
    initSDK();
    }, false)
    } else if (scriptEl.attachEvent) {
    scriptEl.attachEvent('onreadystatechange', function () {
    var target = window.event.srcElement;
    if (target.readyState === 'loaded') {
    initSDK();
    }
    })
    }

    })();
    }
    } catch (e) {
    console.log("同屏技术 error", e)
    }

