                    //banner图片切换
                    (function () {
                    var bannerData=[];
                    var bannerType = ""
                    if(location.href.indexOf("jiankangbaoxian.shtml") > -1){
                    bannerType = "HEALTHY";
                    }else if(location.href.indexOf("yiwaibaoxian.shtml") > -1){
                    bannerType = "ACCIDENT";
                    }else if(location.href.indexOf("qiyebaoxian.shtml") > -1){
                    bannerType = "ENTERPRISE";
                    }else if(location.href.indexOf("lvyoubaoxian.shtml") > -1){
                    bannerType = "TOUR";
                    }else if(location.href.indexOf("caichanbaoxian.shtml") > -1){
                    bannerType = "PROPERTY";
                    }else {
                    bannerType = "HOME";
                    }
                    $.ajax({
                    type:"get",
                    url:"/pa18shopnst/do/websiteBanner/getBannerByType?bannerType=" + bannerType,
                    async:false,
                    dataType: "json",
                    success: function (res) {
                    if(res.resultCode == "200"){
                    var bannerPictureDTOList = res.data.bannerPictureDTOList;
                    for(var i = 0;i< bannerPictureDTOList.length;i++){
                    var item = bannerPictureDTOList[i];
                    var bannerItem = {
                    imgUrl: item.picUrl,
                    url: item.targetUrl
                    }
                    bannerData.push(bannerItem);
                    }
                    }else {
                    console.error && console.error(res.resultMsg);
                    }
                    },
                    error: function () {
                    console.error && console.error('网络错误，请稍后再试！');
                    }
                    })
                    //IE 验证一下
                    if(  $("#rollist").length==0 ){
                    throw new Error("banner error");
                    return;
                    }
                    var sTemp='';
                    $.each(bannerData,function(idx,item){
                    if( item.hide ) return true;
                    sTemp+='
'
                    sTemp+=''
                    sTemp+=''
                })
                //生成banner轮播图html元素
                $("#rollist").html(sTemp);

                var roldot_Arr=[];
                $("#rollist .rollist_li").each(function(idx){
                if( idx==0 ){
                $(this).show();
                }
                roldot_Arr.push("
");
                })
                $("#roldot_Box").append(roldot_Arr.join(""))
                $("#roldot_Box li").eq(0).addClass("active");

                var i = 0;
                var j = 1;
                $('#roldot_Box li').on('click', function () {
                var index = $(this).index();
                $(this).addClass('active').siblings().removeClass('active');
                $('.rollist').find('>li').eq(index).fadeIn(500).siblings().fadeOut(500);
                i = index;
                })
                //点击右边按钮滚动
                $(".next_btn").click(function () {
                move();
                })
                //点击左边按钮滚动
                $(".prev_btn").click(function () {
                j--;
                $('.rollist').find('>li').eq(j - 1).fadeIn(500).siblings().fadeOut(500);
                $('.roldot').find('>li').eq(j - 1).addClass('active').siblings().removeClass('active');
                if (j == 0) {
                j = $('.rollist').find('>li').length;
                $('.rollist').find('>li').eq(j).fadeIn(500).siblings().fadeOut(500);
                }
                i = j - 1;
                })
                function move() {
                $('.rollist').find('>li').eq(i).fadeIn(500).siblings().fadeOut(500);
                $('.roldot').find('>li').eq(i).addClass('active').siblings().removeClass('active');
                i++;
                if (i == $('.rollist').find('>li').length) {
                i = 0;
                }
                }
                setInterval(move, 5000);
                })()

