body.script:
(function () {
Array.prototype.my_filter = function (callback) {
if (!Array.isArray(this) || !this.length || typeof callback !== 'function') {
return []
} else {
var result = [];
for (var index = 0; index < this.length; index++) {
var item = this[index];
if (callback(item, index, this)) {
result.push(item)
}
}
return result
}
}
var CategoryProductsAll = JSON.parse(window.sessionStorage.getItem("CategoryProductsAll"))
if(CategoryProductsAll && Object.keys(CategoryProductsAll).length !== 0){
CategoryProductsAll = CategoryProductsAll.my_filter(function(item){
return item.categoryCode == "PC_HEALTHY"
})
dealProductsHEALTHY(CategoryProductsAll);
}else {
$.ajax({
type:"get",
url:"/pa18shopnst/do/era/shopProduct/queryCategoryProducts?categoryCode=PC_HEALTHY",
async:false,
dataType: "json",
success: function (res) {
if(res.resultCode == "200"){
$("#all_product_list").empty()
var datas = res.data;
dealProductsHEALTHY(datas);
}else {
console.error && console.error('产品类型查询失败，请重新试试！');
}
},
error: function () {
console.error && console.error('网络错误，请重新试试！');
}
})
}
function dealProductsHEALTHY(datas){
for(var I = 0;I < datas.length;I++){
var Item = datas[I];
for(var i = 0;i < Item.categoryProducts.length;i++){
var item = Item.categoryProducts[i]
if(item.hotProductFlag == "Y"){
item.hotProductFlag = true;
}else {
item.hotProductFlag = false;
}
var urlParams = window.location.search;
if(urlParams && item.productUrl.indexOf("?") != -1){
urlParams = urlParams.replace("?", "&")
item.productUrl = item.productUrl + urlParams;
}else if(urlParams && item.productUrl.indexOf("?") == -1){
item.productUrl = item.productUrl + urlParams;
}
if(!item.priceUnit){
item.priceUnit = "/起"
}
var template = $('#productTemplate').html();
var html = Mustache.to_html(template,item);
$("#all_product_list").append(html);
}
}
}
})();

//分页，显示更多
$(".list_pro_morebtn").click(function () {
var len = $(".list_product li").length - 1;
show_click_img(len);
$(".list_pro_more").css("display", "none");
});

function show_click_img(li_num) {
if (li_num < 17) {
$(".list_pro_more").css("display", "none");
} else {
$(".list_pro_more").css("display", "block");
}
$(".list_product li").css("display", "none");
$(".list_product li").eq(li_num).prevAll().css("display", "block").animate({}, 1000, function () {


});
$(".list_product li").eq(li_num).css("display", "block").animate({}, 1000, function () {

});
}
//默认显示5个产品，点击更多显示剩余的产品
var len = $(".list_product li").length - 1;
len = len < 17 ? len : 17;
show_click_img(len);

